SELECT AVG(fail_rate) AS avg_fail_rate, COUNT(*) AS course_sem_cnt
FROM vw_course_stats
WHERE department_name ILIKE '%Công nghệ thông tin%' AND semester IS NOT NULL AND total_students >= 5;

SELECT AVG(failure_rate) AS avg_fail_rate, COUNT(*) AS course_sem_cnt
FROM vw_course_stats
WHERE department_name ILIKE '%Công nghệ thông tin%' AND semester IS NOT NULL AND total_students >= 5;

SELECT AVG(fail_rate_avg::float) AS avg_fail_rate, COUNT(*) AS course_sem_cnt
FROM vw_course_stats
WHERE program_id IN (
  SELECT program_id FROM vw_program_stats WHERE program_name ILIKE '%Công nghệ thông tin%' 
)
AND semester_id IS NOT NULL AND total_students >= 5;

SELECT AVG(fail_rate_avg::float) AS avg_fail_rate, COUNT(*) AS course_sem_cnt
FROM vw_course_stats
WHERE semester_id IS NOT NULL AND total_students >= 5 AND program_id = 1;

SELECT *
FROM vw_program_stats
LIMIT 5;

SELECT COUNT(*) AS opened_sections
FROM vw_section_stats
WHERE course_name ILIKE '%Lập trình hướng đối tượng%';

SELECT *
FROM vw_course_stats
LIMIT 1;

